<template><div class="dash-stack"><div class="dash-toolbar"><div><h2>My lands</h2><p>Read-only records where your account email is listed as an owner.</p></div></div><div class="glass-panel"><div v-if="loading" class="state-message">Loading your land records…</div><div v-else-if="!result.items?.length" class="state-message">No land records are currently linked to your account.</div><div v-else class="record-grid"><article v-for="land in result.items" :key="land.landId" class="record-card"><div class="record-top"><span class="record-label">LAND ID</span><span class="status-tag">{{land.overallStatus||'Not assessed'}}</span></div><h3>{{land.landId}}</h3><p>{{land.area?.mouza}}, {{land.area?.upazila}}, {{land.area?.district}}</p><div class="record-meta"><span>Dag {{land.dagNo}}</span><span>{{land.recordType}}</span></div><div class="record-owner-preview">{{(land.owners||[]).map((o)=>o.ownerEmail).join(' · ')||'No owners recorded'}}</div><div class="record-actions"><IconButton :icon="expandedId===land.landId?'collapse':'expand'" :label="expandedId===land.landId?'Collapse details':'View more details'" @click="expandedId=expandedId===land.landId?null:land.landId"/></div><LandDetailsPanel v-if="expandedId===land.landId" :land="land"/></article></div><div class="pagination"><span>Page {{result.page||1}} of {{result.totalPages||0}}</span><div><IconButton icon="previous" label="Previous page" :disabled="!result.hasPrevious" @click="load((result.page||1)-1)"/><IconButton icon="next" label="Next page" :disabled="!result.hasNext" @click="load((result.page||1)+1)"/></div></div></div></div></template>
<script setup lang="ts">import{onMounted,ref}from'vue';import{platformApi}from'@/services/platform';import IconButton from'@/components/ui/IconButton.vue';import LandDetailsPanel from'@/components/ui/LandDetailsPanel.vue';const result=ref<any>({items:[]}),loading=ref(false),expandedId=ref<string|null>(null);async function load(page=1){loading.value=true;try{result.value=(await platformApi.userLands(page)).data}finally{loading.value=false}}onMounted(()=>load());</script>
